+import qs from 'qs';
+import { RouteState } from '../../types';
+
+type BrowserHistoryProps = {
+  windowTitle?: (routeState: RouteState) => string;
+  writeDelay: number;
+  createURL({
+    qsModule,
+    routeState,
+    location,
+  }: {
+    qsModule: typeof qs;
+    routeState: RouteState;
+    location: Location;
+  }): string;
+  parseURL({
+    qsModule,
+    location,
+  }: {
+    qsModule: typeof qs;
+    location: Location;
+  }): RouteState;
+};
+
+const defaultCreateURL: BrowserHistoryProps['createURL'] = ({
+  qsModule,
+  routeState,
+  location,
+}): string => {
+  const { protocol, hostname, port = '', pathname, hash } = location;
+  const queryString = qsModule.stringify(routeState);
+  const portWithPrefix = port === '' ? '' : `:${port}`;
+
+  // IE <= 11 has no proper `location.origin` so we cannot rely on it.
+  if (!routeState || Object.keys(routeState).length === 0) {
+    return `${protocol}//${hostname}${portWithPrefix}${pathname}${hash}`;
+  }
+
+  return `${protocol}//${hostname}${portWithPrefix}${pathname}?${queryString}${hash}`;
+};
+
+const defaultParseURL: BrowserHistoryProps['parseURL'] = ({
+  qsModule,
+  location,
+}): RouteState => {
+  // `qs` by default converts arrays with more than 20 items to an object.
+  // We want to avoid this because the data structure manipulated can therefore vary.
+  // Setting the limit to `100` seems a good number because the engine's default is 100
+  // (it can go up to 1000 but it is very unlikely to select more than 100 items in the UI).
+  //
+  // Using an `arrayLimit` of `n` allows `n + 1` items.
+  //
+  // See:
+  //   - https://github.com/ljharb/qs#parsing-arrays
+  //   - https://www.algolia.com/doc/api-reference/api-parameters/maxValuesPerFacet/
+  return qsModule.parse(location.search.slice(1), { arrayLimit: 99 });
+};
+
+const setWindowTitle = (title?: string): void => {
+  if (title) {
+    window.document.title = title;
+  }
+};
+
